{"code":"import json, time
with open('table.json') as f: tbl=json.load(f)
syms='ABCDE'; enc={c:i for i,c in enumerate(syms)}
T=[0]*125
for k,v in tbl.items(): T[enc[k[0]]*25+enc[k[1]]*5+enc[k[2]]]=enc[v]
a=tuple(enc[c] for c in open('start.txt').read().strip())

# baseline function
Tloc=T

def step1(a):
    n=27
    b=[0]*n
    for i in range(n):
        b[i]=Tloc[a[i-1]*25+a[i]*5+a[(i+1)%n]]
    return tuple(b)

# generated unrolled
lines=['def step2(a,T=Tloc):']
for i in range(27):
    l=(i-1)%27; r=(i+1)%27
    lines.append(f'    v{i}=T[a[{l}]*25+a[{i}]*5+a[{r}]]')
lines.append('    return ('+','.join(f'v{i}' for i in range(27))+',)')
ns={'Tloc':Tloc}
exec('\n'.join(lines), ns)
step2=ns['step2']

for fn in [step1,step2]:
    x=a
    st=time.time(); N=500000
    for _ in range(N):
        x=fn(x)
    print(fn.__name__, time.time()-st)
